<script setup>
import{computed,onMounted,reactive,ref,watch}from'vue';import{useRouter}from'vue-router';import api,{errorMessage,validationErrors}from'../../composables/useAdminApi';import AdminPageHeader from'../../components/AdminPageHeader.vue';import DynamicFormRenderer from'../../components/DynamicFormRenderer.vue';const router=useRouter();const steps=['Client','Service','Project','Configuration','Deliverables','Contacts','Contract','Review'];const step=ref(0),lookups=ref({companies:[],service_products:[]}),setup=ref(null),contacts=ref([]),saving=ref(false),error=ref(''),errors=ref({});const form=reactive({company_id:'',service_product_id:'',name:'',url:'',summary:'',portal_status:'draft',started_at:'',completed_at:'',internal_notes:'',configuration:{},selected_deliverable_ids:[],contact_ids:[],contract_values:{}});onMounted(async()=>lookups.value=(await api.get('/lookups')).data);watch(()=>form.company_id,async id=>{contacts.value=id?(await api.get(`/companies/${id}/contacts/options`)).data:[];form.contact_ids=[]});watch(()=>form.service_product_id,async id=>{if(!id)return;setup.value=(await api.get(`/service-products/${id}/blueprint`)).data;const fields=setup.value.version?.fields||[];form.configuration=Object.fromEntries(fields.map(f=>[f.key,f.default_value]));form.selected_deliverable_ids=(setup.value.version?.deliverables||[]).filter(d=>d.requirement_level==='required'||(d.requirement_level==='recommended'&&d.default_selected)).map(d=>d.id)});const canNext=computed(()=>step.value===0?Boolean(form.company_id):step.value===1?Boolean(form.service_product_id&&setup.value?.readiness.ready):step.value===2?Boolean(form.name):true);function selected(item){return item.requirement_level==='required'||form.selected_deliverable_ids.includes(item.id)}function toggle(item){if(item.requirement_level==='required')return;const i=form.selected_deliverable_ids.indexOf(item.id);i>=0?form.selected_deliverable_ids.splice(i,1):form.selected_deliverable_ids.push(item.id)}async function submit(){saving.value=true;errors.value={};try{const response=await api.post('/projects',form);router.push({name:'projects.show',params:{id:response.data.data.id}})}catch(e){errors.value=validationErrors(e);error.value=errorMessage(e)}finally{saving.value=false}}
</script>
<template><div class="space-y-6"><AdminPageHeader title="Create project" eyebrow="Service factory" description="The published blueprint and contract version will be snapshotted into this project."/><ol class="grid grid-cols-4 gap-px border border-dark bg-dark lg:grid-cols-8"><li v-for="(name,index) in steps" :key="name" class="bg-light p-3 text-center font-mono text-[10px] font-bold uppercase" :class="index===step?'!bg-accent':''">{{index+1}}. {{name}}</li></ol><p v-if="error" class="border border-red-700 bg-red-50 p-3 text-red-700">{{error}}</p><section class="min-h-[420px] border border-dark bg-light p-5 sm:p-8"><div v-if="step===0" class="admin-field max-w-xl"><label>Client</label><select v-model="form.company_id"><option value="">Select client…</option><option v-for="company in lookups.companies" :key="company.id" :value="company.id">{{company.display_name||company.name}}</option></select></div><div v-if="step===1" class="space-y-5"><div class="admin-field max-w-xl"><label>Service</label><select v-model="form.service_product_id"><option value="">Select service…</option><option v-for="product in lookups.service_products.filter(p=>p.active)" :key="product.id" :value="product.id">{{product.name}}</option></select></div><article v-if="setup" class="max-w-xl border p-4"><strong>{{setup.readiness.ready?'Ready':'Setup incomplete'}}</strong><p v-for="missing in setup.readiness.missing" :key="missing" class="mt-1 text-sm">Missing {{missing.replaceAll('_',' ')}}</p></article></div><div v-if="step===2" class="grid gap-4 sm:grid-cols-2"><div class="admin-field"><label>Project name</label><input v-model="form.name"></div><div class="admin-field"><label>Status</label><select v-model="form.portal_status"><option>draft</option><option>active</option><option>on_hold</option></select></div><div class="admin-field sm:col-span-2"><label>Description</label><textarea v-model="form.summary" rows="4"></textarea></div><div class="admin-field"><label>Start date</label><input v-model="form.started_at" type="date"></div><div class="admin-field"><label>Completion date</label><input v-model="form.completed_at" type="date"></div></div><DynamicFormRenderer v-if="step===3" v-model="form.configuration" :fields="setup?.version?.fields||[]"/><div v-if="step===4" class="space-y-2"><label v-for="item in setup?.version?.deliverables||[]" :key="item.id" class="flex gap-3 border p-4"><input type="checkbox" :checked="selected(item)" :disabled="item.requirement_level==='required'" @change="toggle(item)"><span><strong>{{item.name}}</strong><small class="block uppercase text-neutral-500">{{item.requirement_level}} · {{item.expected_resource_type}}</small></span></label></div><div v-if="step===5" class="space-y-2"><label v-for="contact in contacts" :key="contact.id" class="flex gap-3 border p-4"><input v-model="form.contact_ids" type="checkbox" :value="contact.id"><span>{{contact.first_name}} {{contact.last_name}}<small class="block">{{contact.email}}</small></span></label><p v-if="!contacts.length">No active contacts for this client.</p></div><div v-if="step===6" class="space-y-5"><article class="border p-4"><strong>{{setup?.readiness.template?.name}}</strong><p>Published version {{setup?.readiness.contractVersion?.version}}</p></article><DynamicFormRenderer v-model="form.contract_values" :fields="setup?.readiness.contractVersion?.field_definitions||[]"/></div><dl v-if="step===7" class="grid max-w-2xl grid-cols-[180px_1fr] gap-y-3"><dt>Client</dt><dd>{{lookups.companies.find(c=>c.id===form.company_id)?.name}}</dd><dt>Service</dt><dd>{{lookups.service_products.find(p=>p.id===form.service_product_id)?.name}}</dd><dt>Project</dt><dd>{{form.name}}</dd><dt>Blueprint</dt><dd>{{setup?.readiness.blueprintVersion?.version}}</dd><dt>Contract</dt><dd>{{setup?.readiness.template?.name}} v{{setup?.readiness.contractVersion?.version}}</dd><dt>Deliverables</dt><dd>{{form.selected_deliverable_ids.length}}</dd><dt>Folders</dt><dd>{{setup?.version?.folders?.length||0}}</dd><dt>Contacts</dt><dd>{{form.contact_ids.length}}</dd></dl></section><footer class="flex justify-between"><button class="admin-button" :disabled="step===0" @click="step--">Previous</button><button v-if="step<7" class="admin-button bg-dark text-light" :disabled="!canNext" @click="step++">Next</button><button v-else class="admin-button bg-dark text-light" :disabled="saving" @click="submit">{{saving?'Creating…':'Create project'}}</button></footer></div></template>